import{Z as t,e as o,f as s,a0 as n}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"GoCardless","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/gocardless.md","filePath":"integrations/payments/gocardless.md","lastUpdated":1782188602000}'),a={name:"integrations/payments/gocardless.md"};function i(r,e,l,c,h,d){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="gocardless" tabindex="-1">GoCardless <a class="header-anchor" href="#gocardless" aria-label="Permalink to &quot;GoCardless&quot;">​</a></h1><p>Connect GoCardless to take payments through the provider configured for your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><p>Formie uses GoCardless <strong>Billing Request Flows</strong> for hosted Direct Debit authorisation. After the customer authorises their bank details, Formie creates a one-off payment or recurring subscription against the mandate and tracks status through webhooks and the status page.</p><blockquote><p>Direct Debit payments are asynchronous. Customers are redirected back to your site while GoCardless collects the payment over the next few business days. One-off submissions finalise when GoCardless confirms the payment. Subscription submissions finalise once the GoCardless subscription is active.</p></blockquote><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>GoCardless</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-gocardless-api" tabindex="-1">Step 2. Connect to the GoCardless API <a class="header-anchor" href="#step-2-connect-to-the-gocardless-api" aria-label="Permalink to &quot;Step 2. Connect to the GoCardless API&quot;">​</a></h3><ol><li>Go to the <a href="https://manage.gocardless.com/" target="_blank">GoCardless Dashboard</a> (or use the <a href="https://manage-sandbox.gocardless.com/" target="_blank">sandbox environment</a> for testing).</li><li>Navigate to <strong>Developers</strong> → <strong>Developers</strong>.</li><li>Click the <strong>Create Access Token</strong> button.</li><li>Copy the <strong>Access Token</strong> from GoCardless and paste it in the <strong>Access Token</strong> field in Formie.</li></ol><h3 id="step-3-configure-webhooks" tabindex="-1">Step 3. Configure Webhooks <a class="header-anchor" href="#step-3-configure-webhooks" aria-label="Permalink to &quot;Step 3. Configure Webhooks&quot;">​</a></h3><ol><li>In the GoCardless dashboard, create a webhook endpoint pointing to your Formie webhook URL:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-site.test/formie/payment-webhooks/process-webhook?handle=yourGoCardlessHandle</span></span></code></pre></div><ol start="2"><li>Copy the webhook signing secret into Formie’s <strong>Webhook Secret Key</strong> field.</li><li>Enable payment, billing request, and subscription events in GoCardless.</li></ol><p>Formie listens for payment status updates, billing request fulfilment, and subscription lifecycle events. Do not rely on the customer redirect alone to confirm payment status.</p><h3 id="step-4-test-connection" tabindex="-1">Step 4. Test Connection <a class="header-anchor" href="#step-4-test-connection" aria-label="Permalink to &quot;Step 4. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-5-field-settings" tabindex="-1">Step 5. Field Settings <a class="header-anchor" href="#step-5-field-settings" aria-label="Permalink to &quot;Step 5. Field Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select GoCardless for the <strong>Payment Provider</strong>.</li><li>Choose <strong>Once-off</strong> or <strong>Subscription</strong> for the <strong>Payment Type</strong>.</li><li>Configure the payment <strong>Currency</strong> and <strong>Amount</strong>.</li><li>For subscriptions, configure the billing frequency and subscription description.</li><li>Optionally map <strong>Billing Details</strong> so Formie can prefill customer details on the GoCardless hosted page.</li></ol><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><h3 id="once-off-payments" tabindex="-1">Once-Off Payments <a class="header-anchor" href="#once-off-payments" aria-label="Permalink to &quot;Once-Off Payments&quot;">​</a></h3><ol><li>The customer submits your form.</li><li>Formie creates a GoCardless <strong>Billing Request</strong> and <strong>Billing Request Flow</strong>.</li><li>The customer is redirected to GoCardless to authorise Direct Debit.</li><li>When they return, Formie creates the payment against the mandate and shows the status page.</li><li>GoCardless webhooks update the payment status as collection progresses.</li></ol><h3 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h3><ol><li>The customer submits your form.</li><li>Formie creates a GoCardless <strong>Billing Request</strong> and <strong>Billing Request Flow</strong> for mandate authorisation.</li><li>The customer is redirected to GoCardless to authorise Direct Debit.</li><li>When they return, Formie creates a GoCardless <strong>Subscription</strong> against the mandate.</li><li>GoCardless collects recurring payments automatically. Formie tracks subscription status and upcoming payment dates via webhooks.</li></ol><p>Customers can cancel subscriptions using Formie’s subscription cancel URL when included in notifications.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><strong>Direct Debit only</strong> — Instant Bank Pay and combined instant + Direct Debit flows are not supported yet.</li><li><strong>Scheme selection</strong> is inferred from the payment currency (for example GBP → BACS, EUR → SEPA).</li><li><strong>Subscription intervals</strong> support weekly, monthly, and yearly billing only.</li><li><strong>Setup fees, payment limits, and trials</strong> are not supported for GoCardless subscriptions.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Pending billing request but no payment amount in GoCardless</strong> — Formie creates the payment or subscription after the customer completes the hosted authorisation flow. Check that webhooks are configured and that the customer returned to the Formie status page.</p><p><strong>Payment stays pending</strong> — This is normal for Direct Debit until GoCardless confirms collection. Use webhooks or wait for the status page polling to refresh.</p><p><strong>Subscription active but submission still incomplete</strong> — Ensure webhooks are configured and that the status page can refresh the subscription state. The submission finalises once the GoCardless subscription is active.</p><p><strong>Sandbox testing</strong> — Enable <strong>Use Sandbox</strong> on the integration and use sandbox API credentials.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Complete a test payment and inspect both the saved submission and the provider’s transaction record. Confirm the amount, currency and final payment state before enabling live payments.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',34)])])}const g=t(a,[["render",i]]);export{p as __pageData,g as default};
